class Solution:
    def reachNumber(self, target: int) -> int:
        target = abs(target)
        k = 0
        total = 0
        while total < target or (total - target) % 2 != 0:
            k += 1
            total += k
        return k

class Solution {
public:
    int reachNumber(int target) {
        long long t = abs((long long)target);
        long long k = 0, total = 0;
        while (total < t || (total - t) % 2 != 0) {
            k++;
            total += k;
        }
        return k;
    }
};

class Solution {
